contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public {
        uint256 fromBalBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 fromBalAfter = c.balanceOf(address(this));
        uint256 toBalAfter = c.balanceOf(to);

        assert(reverted ? (fromBalAfter == fromBalBefore && toBalAfter == toBalBefore) : (fromBalAfter + amount == fromBalBefore && toBalAfter == toBalBefore + amount));
    }
}
